// Type declarations for vite-imagetools query imports.
declare module "*&as=srcset" {
  const src: string;
  export default src;
}
declare module "*&quality=78" {
  const src: string;
  export default src;
}
declare module "*.jpg?*" {
  const src: string;
  export default src;
}
declare module "*.jpeg?*" {
  const src: string;
  export default src;
}
declare module "*.png?*" {
  const src: string;
  export default src;
}
